// Portable, source-checked transcription and editorial answers. No invented exam items.
// Lesson pages refer to the archived 24-page first-term notes; section IDs refer
// only to substantive teaching in the unchanged, hash-locked review PDF.
const quran = (...verses) => verses.map(v => `Primary text, Quran ${v}: https://quran.com/${v.replace(':', '/')}`);
const sayings = 'https://al-islam.org/nahjul-balagha-part-2-letters-and-sayings/selections-sayings-and-preaching-amir-al-muminin-ali';
const topics = {
  foundations: ['Foundations of divine morality', [1, 2]],
  definitions: ['Khulq, khalq and ethical research', [3, 4, 5]],
  learning: ['Piety, purification and learning', [6, 7, 8]],
  moderation: ['Moderation and balance between faculties and duties', [8, 9, 10]],
  trust: ['Trust in God and responsible effort', [10, 11, 12]],
  humility: ['Humility and arrogance', [13, 14, 15, 16]],
  anger: ['Anger and self-control', [16, 17, 18]],
  honesty: ['Honesty and trustworthiness', [19, 20, 21]],
  patience: ['Patience and perseverance', [21, 22]],
  forgiveness: ['Forgiveness and good conduct toward others', [22, 23]],
  intention: ['Intention, sincerity and moral action', [2, 7]],
  faith: ['Faith, knowledge and conduct', [1, 2, 7]],
  speech: ['Ethical speech, suspicion and backbiting', [19, 20, 21]],
};
const question = (number, page, theme, prompt, options, key, note, extra = {}) => ({
  number, page, prompt, options, key, providedKey: null, inferred: true,
  topic: topics[theme][0], lessonPages: topics[theme][1], sectionId: null, note, ...extra,
});
const section = (id, reviewNote) => ({sectionId: `divine-ethics/${id}`, reviewNote});
const reviewed = {
  status: 'reviewed', date: '2026-10-06',
  method: 'Source wording and option order checked against original pages/native text; answers compared with the current review, first-term notes and specified primary passages. Content relevance is not official course-code authentication. No official key is asserted.',
};
function paper(id, title, count, note, questions, extra = {}) {
  return {
    id: `divine-ethics-${id}`, title, note, kind: questions.length === count ? 'source-paper' : 'selected-source-questions',
    courseLevel: 1, courseEvidenceType: 'content-match',
    courseEvidence: 'Admitted by question-level comparison with the supplied review and first-term lessons, as requested. The original lacks a confirmed university I/II course code; content match is not a claim of official enrollment or syllabus completeness.',
    dateEvidence: 'Sitting date not established; no date is inferred from a download or Telegram posting.',
    defaultEligible: true, originalOrderClaim: true, originalSourceCount: count,
    missingSourceNumbers: [], excludedSourceNumbers: Array.from({length: count}, (_, i) => i + 1).filter(n => !questions.some(q => q.number === n)),
    audit: reviewed, questions, ...extra,
  };
}

export const photo30 = paper('first-term-photo-30', 'Divine Ethics · 30-question photographed paper', 30,
  'Complete Q1–30 body from five photographs (printed pages 3–7). Strong first-term lesson-content match; cover, sitting date and official I/II label are unavailable. This is a different sequence from the existing Q3–12 fragment. Study answers are checked editorial answers, not an official key. Some lessons are absent from the current review and link to the first-term notes instead.', [
  question(1, 1, 'foundations', 'The goal of the prophets, especially the Prophet of Islam, was to train and educate people to achieve:', ['Only the hereafter.', 'Material prosperity.', 'Occupation of other countries.', 'High goals.'], 'D', 'Lesson 1, p. 1 states the goal as educating people to attain higher goals and purify their thoughts. The other choices narrow or contradict the course account.'),
  question(2, 1, 'foundations', 'Which of the following principles of divine morality does this verse refer to?\nيوم تجد كل نفس ما عملت من خير محضرا وما عملت من سوء', ['Divine supervision.', 'Belief in the resurrection.', 'Divine revelation.', 'None.'], 'B', 'The photograph quotes the opening of Quran 3:30, describing the Day when each soul is confronted with its good and evil deeds. Thus B, belief in resurrection and accountability, is the most specific principle. Do not confuse it with the different verse about divine supervision in the separate Q3–12 fragment. First-term Lesson 1, p. 2 links resurrection to judgment of actions.', {evidence: quran('3:30')}),
  question(3, 1, 'foundations', 'Which one is the most important source of knowledge for the followers of the heavenly religions?', ['Intuitive source.', 'Empirical source.', 'Wisdom.', 'Revelation.'], 'D', 'Lesson 1, question 6, p. 2 explicitly identifies revelation as the foremost source in this theological framework. This is not a rejection of empirical methods in science.'),
  question(4, 1, 'definitions', 'According to Ibne Muskawiyyah, “kholq” is:', ['One of the traits of the human self which entices man to carry out his daily affairs without thinking.', 'One of the traits of the human self which entices man to carry out his daily affairs with thinking.', 'One of the traits of the human self which entices man to carry out his daily affairs with a lot of thought.', 'One of the traits of the human self which entices man to carry out his daily affairs without authority.'], 'A', 'Lesson 2, p. 3 describes an established disposition producing actions without fresh deliberation. It can become habitual through practice; the answer does not say that moral action must be mindless.'),
  question(5, 1, 'definitions', 'Which one is true about Khulq?', ['Consists of the good or bad qualities.', 'It is internalization of good or bad qualities.', 'Virtues or vices which are shaped over time.', 'All of the above.'], 'D', 'The first-term definition includes internal moral qualities, good or bad, developed as character. All three descriptions fit Lesson 2; khulq is not the visible bodily form khalq.'),
  question(6, 1, 'definitions', 'Which one is NOT true about the knowledge of ethics (science of Akhlaq)?', ['It identifies good and bad behaviors.', 'In the knowledge of ethics we study Khulq and Khalq.', 'It studies good and bad actions.', 'It deals with human characteristics and traits like vices and virtues.'], 'B', 'The course distinguishes moral character, khulq, from bodily creation, khalq. Its science-of-ethics definition studies moral traits and associated actions, not bodily creation as such. See first-term pp. 3–4.'),
  question(7, 2, 'learning', 'What does cultivation (tazkiye) mean?', ['Cultivation means restoring the human soul and nature to its original and natural purity and honesty.', 'Cultivation means doing a lot of worship.', 'Cultivation means serving the people and one’s family.', 'Cultivation means forgetting sins and doing new worship.'], 'A', 'This reproduces Lesson 3, question 2, p. 7. Cultivation concerns purification, rather than forgetting wrongs or simply accumulating acts.'),
  question(8, 2, 'foundations', 'What plays an important role in creating human behavior?', ['Power.', 'Fear.', 'Courage.', 'Reminder of death.'], 'D', 'The source uses the broad wording “creating human behavior”. Within Lesson 1, p. 2 the intended point is that preparation for death helps correct conduct. It is not a universal claim that the other factors never affect behavior.', section('sep17-sincerity-practice', 'Remembering death and impermanence as a corrective to ostentation, review pp. 6–7.')),
  question(9, 2, 'moderation', 'When do problems start in our life?', ['When we commit a small sin.', 'When we lose our balance.', 'When we do not tell our problems to others.', 'When we try hard.'], 'B', 'The intended answer comes from the moderation lesson: imbalance between faculties and responsibilities. This source-specific generalization must not be read as blaming every real-life problem on personal imbalance.'),
  question(10, 2, 'moderation', 'In Aristotle’s approach to ethics, when are virtues revealed?', ['When we lose balance and go to extremes.', 'Virtues are found only when we work full time.', 'Virtues are found only when we create balance.', 'Virtues are found only when we study full time.'], 'C', 'Lesson 4, pp. 8–9 locates the virtue at the balanced mean between excess and deficiency. The full Aristotelian-faculties lesson is not reproduced in the review.'),
  question(11, 2, 'definitions', 'In which ethical research do we use the method of logical coercion?', ['Ethics of commanding and forbidding.', 'Descriptive ethics.', 'Meta-ethics.', 'None.'], 'A', 'Lesson 2, pp. 4–5 gives “logical coercion” as the course term for commanding-and-forbidding ethics. Descriptive ethics instead uses historical/narrative description.'),
  question(12, 2, 'trust', 'Why should believers not trust in any other person or thing apart from God?', ['A believer knows that this world belongs to God.', 'A believer knows that this world was created by God.', 'Everyone else is fully dependent on God.', 'All of the above are true.'], 'D', 'All three fit the course’s account of divine ownership and dependent causes. The stem concerns ultimate, independent reliance; using people, medicine and ordinary means remains compatible with trust. See the review pp. 5, 8 and 18.', section('sep17-trust', 'Trust includes responsible use of dependent natural means.')),
  question(13, 3, 'trust', 'Why do we say that God knows everything?', ['He knows about all our friends, enemies, problems and their solution.', 'He is aware of all of our needs.', 'He knows the best way for our needs to be met.', 'All of the above.'], 'D', 'Lesson 5, pp. 10–11 states each of these as reasons for trust in the course’s theological account.', section('tawakkul', 'Trust in a benevolent, knowledgeable and powerful God, review p. 18.')),
  question(14, 3, 'trust', 'Which phrase is more complete for the meaning of trusting in God?', ['Performing complete worship.', 'We do our very best and after this we leave the result in God’s hands.', 'Always wait for God’s help because God helps all His servants.', 'None.'], 'B', 'Tawakkul joins effort, planning and legitimate means with reliance; it is not passive waiting. Lesson 5, p. 11 and the review’s farmers/camel examples support B.', section('sep17-trust', 'Responsible effort rather than inactivity, review pp. 8–9.')),
  question(15, 3, 'humility', 'Which one is true about humility?', ['Understanding your limitations.', 'Strengthening our understanding of our deep need for God.', 'Awareness of our place in this world.', 'All of the above are true.'], 'D', 'All three clauses occur in the definition of humility in Lesson 6, p. 13. The review merely lists humility as a virtue and is not a substitute for that definition.'),
  question(16, 3, 'humility', 'How does a person who has the characteristic of arrogance feel?', ['A person who possesses this trait believes themselves to be in an elevated position; in fact, he/she is also an important person.', 'A person who possesses this trait believes themselves to be in an elevated position when in reality he/she is not.', 'A person who possesses this trait believes themselves to be in an elevated position, while thinking rightly.', 'None.'], 'B', 'Lesson 6, p. 13 defines the trait using imagined elevation unsupported by reality. This tests that particular course definition.'),
  question(17, 3, 'moderation', 'Which of the following words means submission of libido to intellect?', ['Bravery.', 'Modesty.', 'Jealousy.', 'Wisdom.'], 'B', 'The course uses modesty/iffah for appetite regulated by reason. Balanced anger is bravery; balanced reasoning is wisdom. First-term p. 9.'),
  question(18, 3, 'humility', 'How can we be promoted to the highest degree of perfection and closeness to God?', ['By wealth.', 'By working.', 'By science.', 'By humility.'], 'D', 'Lesson 6, p. 14 associates spiritual elevation with humility, explicitly distinguishing it from being elevated by wealth, power or social position.'),
  question(19, 4, 'anger', 'When is anger harmful?', ['Anger is always harmful.', 'Anger is always necessary and never harmful.', 'It is a problem if a person becomes angry and loses control over their words and actions.', 'If a person gets angry and does not do anything, it is harmful.'], 'C', 'Lesson 7, pp. 16–17 distinguishes rationally controlled defensive anger from loss of control. Neither “always harmful” nor “never harmful” captures the distinction.'),
  question(20, 4, 'anger', 'Which one is not correct about anger?', ['If we never get angry.', 'If we hurt others when we are angry.', 'If one is easily angered.', 'All of the above.'], 'D', 'The options are grammatically incomplete: read the stem as asking which listed patterns are undesirable. Lesson 7 rejects chronic indifference, easy provocation and harmful loss of control; therefore all three. This wording caveat is retained rather than inventing a better original question.'),
  question(21, 4, 'anger', 'How can we overcome our anger?', ['Using the principle of retaliation.', 'Having a calm, tolerant temper can combat anger.', 'By hurting others or things.', 'All of the above.'], 'B', 'Lesson 7 advocates regulated responses and calming practices, not retaliation or damage. First-term pp. 17–18.'),
  question(22, 4, 'honesty', 'What is the reward of honesty?', ['The divine hand is with someone who is right to say.', 'They shall have all that they wish for in the presence of their Lord.', 'Heaven.', 'All of the above.'], 'D', 'The first-term honesty lesson (pp. 19–20) teaches divine favor, wishes fulfilled with the Lord and paradise. D is the intended study answer. A is awkwardly translated and its precise “divine hand” attribution is not established in those notes; because B and C are explicitly supported, they are also accepted for this imprecise question. These are religious teachings, not promises of every worldly outcome.', {acceptedOptionIds: ['B', 'C', 'D'], evidence: quran('39:33', '39:34')}),
  question(23, 4, 'patience', 'Which one is NOT true about patience?', ['To stop or prevent bad action.', 'Compromise with everyone, good and bad people.', 'Stopping yourself from negative reactions to things you dislike.', 'Stopping yourself from things you love but which might cause harm if approached without preparation.'], 'B', 'Lesson 9, pp. 21–22 defines patient self-regulation, not unconditional compromise with everyone. Patience permits emotion while controlling damaging speech and conduct.'),
  question(24, 4, 'forgiveness', 'Which one is true about forgiveness?', ['It is an intentional and voluntary process without vengefulness.', 'It is an intentional and voluntary process with vengefulness.', 'It is an unintentional and voluntary process without vengefulness.', 'It is an intentional and involuntary process without vengefulness.'], 'A', 'Lesson 10, p. 22 describes a voluntary, intentional letting go of vengeance. It distinguishes forgiveness from excusing, forgetting or necessarily reconciling.'),
  question(25, 5, 'patience', 'Which one is not a criterion of patience?', ['No complaints on your tongue.', 'Do not complain about God in your heart.', 'Your dealings with people should not be affected.', 'Hurry up to do things.'], 'D', 'The first three reproduce the course’s criteria on p. 21; haste conflicts with thoughtful restraint. This religious exercise does not forbid seeking help or expressing distress.'),
  question(26, 5, 'forgiveness', 'Which option does this verse refer to?\nوإن عاقبتم فعاقبوا بمثل ما عوقبتم به ولئن صبرتم لهو خير للصابرين', ['Punishment (qisas).', 'Patience.', 'Forgiveness.', 'All of the above.'], 'B', 'Quran 16:126 explicitly limits retaliation and commends patience; Lesson 10, p. 23 quotes it. Patience is the preferred lesson answer, but A is also expressly in the wording, so A and B are accepted. Forgiveness is discussed nearby but is not explicit in this quoted verse; “all” is not established.', {acceptedOptionIds: ['A', 'B'], evidence: quran('16:126')}),
  question(27, 5, 'faith', 'According to this Quranic verse, what is the punishment for disdain of God (rejection of the worship of God)?\nإن الذين يستكبرون عن عبادتي سيدخلون جهنم داخرين', ['He will enter Hell contemptible.', 'He stays thirsty and hungry.', 'It is far from God’s mercy.', 'None.'], 'A', 'This is the ending of Quran 40:60. The prayer section of the review cites the verse but does not reproduce this clause, so use the original verse for the exact answer.', {evidence: quran('40:60')}),
  question(28, 5, 'forgiveness', 'What is the meaning of forgiveness?', ['Good wishes for the offender.', 'Forgiveness is intentional.', 'We put aside negative emotions such as vengefulness.', 'All of the above.'], 'D', 'Lesson 10, pp. 22–23 includes intention, relinquishing vengeance and increased ability to wish the offender well. It does not require returning to an unsafe relationship.'),
  question(29, 5, 'definitions', 'Which ethical research is suitable for children from 1 to 7 years old?', ['Descriptive ethics.', 'Ethics of commanding and forbidding.', 'Meta-ethics.', 'None.'], 'A', 'The course’s pedagogical classification assigns descriptive/narrative ethics to young children, command ethics to adolescents and meta-ethics to older learners. First-term pp. 4–5; not a universal developmental law.'),
  question(30, 5, 'forgiveness', 'According to the Quran, who rewards the giver?', ['People.', 'Friends.', 'Parents.', 'God.'], 'D', 'The source says “giver”; the matching Lesson 10 question on p. 23 concerns the person who forgives and reconciles. Quran 42:40 places that reward with God. The translation/context caveat is explicit.', {evidence: quran('42:40')}),
]);

export const report2021 = paper('2021-report-selection', 'Divine Ethics · 2021 report · relevant selection', 20,
  'Fifteen relevant questions selected from the 20-question report tagged September 2021. The TestId 20146 report has the same 20 stems in a different order, with option variations; it is retained as a version, not another exam card. Five ambiguous or insufficiently supported items are excluded. Official I/II designation and sitting date remain unconfirmed. Answers are checked editorial study answers.', [
  question(1, 1, 'speech', 'According to the Quran we should avoid much suspicion because:', ['It is harmful for our heart.', 'We can interpret it in a positive way.', 'It makes hatred among Muslims.', 'Some of it is sinful.'], 'D', 'Quran 49:12 explicitly gives sinfulness of some suspicions as the reason. This is the wording asked for, not a denial that suspicion can also damage relationships.', {evidence: quran('49:12')}),
  question(2, 1, 'learning', 'What is the Islamic view about knowledge?', ['It is enough to merely accumulate information and data.', 'Contemplation is the best type of worship and reliance.', 'It is reading and memorizing facts.', 'It should be accompanied by reasoning and understanding.'], 'D', 'The first-term knowledge lesson emphasizes sound understanding rather than accumulation or memorization alone. The review p. 16 also joins reason with knowledge.', section('self-knowledge', 'Reason and knowledge guide ethical self-building; review p. 16.')),
  question(5, 2, 'moderation', 'What is the best way to speak to God?', ['Only if we are alone can we speak loudly.', 'In case there are some people, we should find somewhere else to recite the Quran.', 'Neither speak in our prayers aloud nor in a low tone.', 'It is good to do it loudly.'], 'C', 'The intended quotation is Quran 17:110: seek a middle way rather than either extreme of loudness or silence. The source option is an abbreviated translation, not a universal rule for every form of prayer.', {evidence: quran('17:110')}),
  question(7, 2, 'humility', 'To be humble means:', ['Do not compare him/herself with those who are lower than him/her.', 'Humiliate him/herself to reach the position of best servant of God.', 'Do not compare him/herself with those who are lower than him/her.', 'Strengthen his/her understanding of profound need for God.'], 'D', 'Lesson 6, p. 13 directly gives D. A and C are duplicated in the original and remain duplicated here. Humility is not self-humiliation.'),
  question(8, 3, 'anger', 'Anger — select the correct statement:', ['Is bad because it makes us lose control over words and actions.', 'Is good in case we harm those who attack us.', 'Should be balanced by being indifferent.', 'Is problematic if one never gets angry or is easily angered.'], 'D', 'The original stem is “Anger:”; a selection instruction is added for clarity. Lesson 7, p. 17 explicitly states the two extremes in D. A wrongly treats all anger as loss of control; the lesson allows appropriately regulated anger.'),
  question(10, 4, 'learning', 'The _____ level of the soul, which is _____, commands us to do bad things, and _____, which is the other level of the soul, blames us for doing something wrong.', ['Highest – al-nafs al-lawwamah – al-nafs al-ammarah.', 'Lowest – al-nafs al-ammarah – al-nafs al-lawwamah.', 'Lowest – al-nafs al-lawwamah – al-nafs al-ammarah.', 'Highest – al-nafs al-ammarah – al-nafs al-lawwamah.'], 'B', 'The commanding self is ammarah; the self-reproaching self is lawwamah. Quran 12:53 and 75:2 establish the names; “lowest” is the paper’s pedagogical ordering. The duplicated standalone question pasted above the original Q10 is an annotation, not an extra exam item.', {evidence: quran('12:53', '75:2')}),
  question(11, 5, 'moderation', 'Who will be rewarded more than the martyrs?', ['The patient.', 'The merciful.', 'The modest.', 'The wise.'], 'C', 'The intended trait is chastity/self-restraint (iffah), translated here as modesty, not shyness. Nahjul Balagha saying 474 compares the reward of one who can sin but remains chaste with the martyr. Its wording is “not greater than”, so the exam’s “more” is stronger than the cited saying; C remains the identifiable intended option.', {evidence: [`Nahjul Balagha, saying 474; qualification preserved: ${sayings}`]}),
  question(12, 5, 'faith', 'The only situation in which God tells us not to obey our parents is:', ['When they are enemies of God.', 'When they ask something wrong.', 'When they ask us to commit a sin.', 'When this thing is unacceptable.'], 'C', 'C is the precise intended principle: no obedience in wrongdoing. Quran 31:15 gives the case of pressure to associate partners with God while still requiring kind companionship. B can express the same principle if “wrong” means sinful, so B is also accepted for the source’s imprecise alternatives.', {acceptedOptionIds: ['B', 'C'], evidence: quran('31:15')}),
  question(13, 5, 'forgiveness', 'Whoever saves one life, it is as if he has:', ['Served his lord in the best way.', 'Saved the lives of all people.', 'Served God on the day of resurrection.', 'Saved the lives of all his nation.'], 'B', 'The comparison is with saving all humanity, Quran 5:32. The verse introduces this teaching as a decree for the Children of Israel. This is an ethical/scriptural question, not a clinical instruction.', {evidence: quran('5:32')}),
  question(14, 5, 'learning', 'Purification of the soul according to the Quran brings:', ['Strengthening of the soul and prosperity.', 'Happiness and prosperity.', 'Piety and happiness.', 'Strengthening of the soul and discernment.'], 'B', 'B corresponds to falah (success/prosperity) in Quran 91:9 and the source’s translation. It is the intended scriptural outcome, not a guarantee of wealth or absence of distress.', {evidence: quran('91:9')}),
  question(15, 6, 'learning', 'Which type of knowledge is necessary for everyone according to Islam?', ['Knowledge which helps us have a better life.', 'Knowledge which is necessary for society.', 'Knowledge which answers the basic and essential questions of everybody.', 'Knowledge which is responsible for the needs of the individual and society.'], 'C', 'The self-knowledge lesson begins with fundamental questions about identity, origin, destination and purpose. C is the most specific match to those essential questions, rather than every field needed by society.', section('self-knowledge', 'Identity, origin, destination and purpose are the guiding questions on review p. 16.')),
  question(16, 6, 'honesty', 'In addition to telling the truth, we should believe in the truth, accept the truth, and:', ['Trust the truth.', 'Avoid lies.', 'Understand the truth.', 'Commit ourselves to the truth.'], 'D', 'Lesson 8, p. 19 requires compliance with truth in action as well as speech and belief. D completes that progression.'),
  question(17, 6, 'moderation', 'What is the connection between business and remembrance of God according to the Quran?', ['We should do all the necessary activities and at the same time remember God.', 'The best way is to divide our time for both equally and have dunya and hereafter.', 'Being busy with dunya is against remembrance of God, so we should detach from dunya.', 'It is better to reduce business and be busy with God to be close to Him.'], 'A', 'Lesson 4, p. 9 quotes Quran 24:37 about trade not distracting from remembrance. Responsible daily work and inward awareness coexist; the review also says time allocations need not be equal.', {...section('sep17-planning', 'Work, worship and rest are balanced by needs and priorities, not necessarily equal durations, review pp. 4–5.'), evidence: quran('24:37')}),
  question(18, 6, 'faith', 'Who are excellent companions whom God has blessed according to the Quran?', ['The prophets, the truthful, the martyrs, the righteous.', 'Imams, the truthful, the martyrs, the righteous.', 'True Muslims, the truthful, the faithful, the righteous.', 'The prophets, the faithful, the martyrs, the righteous.'], 'A', 'Quran 4:69 names these four groups. This exact list is not printed in the current review, so the primary verse is linked instead of a substitute review section.', {evidence: quran('4:69')}),
  question(20, 7, 'patience', '_____ is a form of resistance against problems which _____.', ['Patience – helps one continue toward goals despite all the challenges one may face.', 'Satisfaction – helps one continue toward goals despite all the challenges one may face.', 'Satisfaction – one should withstand it to achieve perfection despite all the challenges.', 'Patience – makes one indifferent and tolerate the situation until matters resolve.'], 'A', 'Lesson 9, pp. 21–22 defines active, regulated perseverance. Patience is neither indifference nor merely waiting for circumstances to resolve themselves.'),
]);

const keyed = (number, page, theme, prompt, options, providedKey, key, note, extra = {}) => question(number, page, theme, prompt, options, key, note, {providedKey, ...extra});
export const compilation99 = paper('compilation-99-selection', 'Divine Ethics · 99-item compilation · relevant selection', 99,
  'Selected foundational, individual-ethics, learning and ethical-conduct questions from the 99-item compilation. Not a complete authenticated exam sitting. Medical rulings, marriage questions, unclear items and redundant copies are excluded. Several printed keys are corrected; all answers are editorially checked and retain the original key in the explanation/download. No official I/II label is claimed.', [
  keyed(1, 1, 'trust', 'According to Islam, where does healing come from?', ['Nature.', 'Physicians.', 'Medicine and drugs.', 'From God; medicine, drugs and other things are just tools.'], 'D', 'D', 'The review p. 8 describes medicine as a dependent cause in its theological account. This does not replace medical treatment; use of effective means is explicitly required.', section('sep17-trust', 'Dependent means and the example of medicine, review p. 8.')),
  keyed(4, 1, 'honesty', 'What does Islam say about the truth?', ['Lying is not that bad.', 'Man is not accountable for his words.', 'The truth will save man and lies will annihilate man.', 'None of the above.'], 'C', 'C', 'Lesson 8, pp. 19–21 connects truthfulness with upright conduct and warns against habitual lying. C expresses the intended religious moral contrast, not a literal prediction about every worldly event.'),
  keyed(8, 2, 'learning', 'Why is human nature unable to distinguish between what is good and what is wrong?', ['Because he wants to make a mistake.', 'Because he did not know what was good in his life.', 'Because he thinks what he is doing is good.', 'Because man polluted his nature with national sins and prejudices.'], 'C', 'D', 'The question overgeneralizes: the course is explaining obscured discernment, not a universal inability. Lesson 3, p. 7 attributes this to corruption of the original disposition and obstructing desires, making D the best supplied choice. The source’s phrase “national sins” is retained as a translation defect. The printed key C does not identify the taught cause.'),
  keyed(12, 3, 'honesty', 'What is the main idea of these traditions? “My most beloved brother to me is the one who offers me my shortcomings as a gift.” “One believer is a mirror to another.”', ['Importance of research.', 'Importance of writing.', 'Importance of criticism.'], 'C', 'C', 'The quoted passages frame constructive feedback as a benefit. First-term p. 21 similarly advises welcoming correction and acknowledging mistakes. The source attributes these sayings; this question tests their stated meaning, not independent authentication of every attribution.'),
  keyed(13, 3, 'learning', 'Which knowledge is the most important one, according to the source’s saying attributed to Imam Musa Kazim?', ['Knowledge that purifies your heart and makes you more intelligent.', 'Knowledge that purifies your heart and shows the corruption of it.', 'Knowledge that purifies your heart and shows other people’s mistakes for you.'], 'B', 'B', 'B is the supplied saying’s self-examination meaning. It agrees with the first-term purification lesson and the review’s self-building account; C shifts the focus to criticizing other people. This retains the compilation’s attribution rather than claiming an independently authenticated chain.'),
  keyed(19, 4, 'learning', 'From the Islamic point of view:', ['Following a person in any form is condemned.', 'To follow a person blindly is not acceptable.', 'We can follow a person only when he is our teacher.'], 'B', 'B', 'The objection is to unreasoning imitation, not learning from people. Quran 2:170 criticizes following ancestors without understanding; the notes p. 7 emphasize sound cognition.', {evidence: quran('2:170')}),
  keyed(20, 4, 'definitions', '“The attributes and features in a soul which automatically generate actions and behavior.” This is the definition of:', ['Faith.', 'Akhlaq.', 'Justice.'], 'B', 'B', 'Lesson 2, pp. 3–4 describes established moral dispositions and resulting behavior. Akhlaq is the appropriate term, not faith or justice alone.'),
  keyed(23, 4, 'learning', 'Asking questions helps a learner improve. Choose the best statement attributed to Imam Ali:', ['Ask to learn and not to humiliate.', 'If you ask you will be rewarded.', 'Ask me questions because I know everything.'], 'A', 'A', 'Nahjul Balagha saying 320 contrasts seeking understanding with obstructive questioning. A captures that distinction; learning is not a way to humiliate.', {evidence: [`Nahjul Balagha, saying 320: ${sayings}`]}),
  keyed(24, 4, 'definitions', 'In English, the word “ethic” is defined as:', ['A system of accepted beliefs that control behavior, with a specific focus on a system based on morals.', 'The study of what is morally right only.', 'The study of what is morally wrong only.'], 'A', 'A', 'A is the only comprehensive option. First-term Lesson 2 includes both good and bad traits and actions. Neither right-only nor wrong-only describes the full field.'),
  keyed(25, 5, 'definitions', 'The three major areas of study within ethics recognized today are:', ['Social ethics, normative ethics and behavioral ethics.', 'Meta-ethics, normative ethics and applied ethics.', 'Behavioral ethics, normative ethics and medical ethics.'], 'B', 'B', 'B is the standard three-area classification used by this compilation. First-term pp. 4–5 explain meta-ethics, prescriptive/command discussion and applied ethics; they also discuss descriptive ethics separately. Do not confuse this classification with the notes’ age-based teaching methods.'),
  keyed(28, 5, 'foundations', 'The _____ was considered one of the philosophies of sending Prophet Muhammad:', ['Knowledge of the Quran.', 'Preaching of people.', 'Enhancement of morals.', 'Enlightenment of Islam.'], 'C', 'C', 'The source’s duplicated blanks are normalized without changing the choices. Lesson 1, p. 1 gives moral training and purification as an aim. C is the intended completion.'),
  keyed(31, 6, 'foundations', 'Which of the following is NOT based on divine morality?', ['Exercise.', 'Religious faith.', 'Spiritual identity.', 'Divine revelation.'], 'A', 'A', 'Read as asking which is not one of the listed foundations. Lesson 1, p. 1 names faith, spiritual identity and revelation. This does not mean physical exercise is immoral.'),
  keyed(35, 6, 'learning', 'Many nations are suffering; the source attributes this to educated rather than illiterate people. Why?', ['Because of the corruption.', 'Because of their arrogance.', 'Because they do not have ethics.', 'Because their knowledge is not based on morals.'], 'D', 'D', 'D states the knowledge-without-moral-guidance contrast taught by the dirty-cup analogy on first-term p. 7. The source’s sweeping premise is a teaching illustration, not an evidence-based attribution of all national suffering.'),
  keyed(36, 7, 'definitions', 'If features and attributes produce good actions they are called _____, and if they produce wrong actions they are called _____.', ['Al-akhlaq, al-razael.', 'Al-khulq.', 'Al-fadael, al-razael.', 'None of the above.'], 'C', 'C', 'Fadael denotes virtues and razael vices in the source terminology. Akhlaq/khulq describe moral character more generally and can include either kind. Compare Lesson 2, pp. 3–4 and review p. 16.', section('self-knowledge', 'The review lists virtues and opposing vices; the Arabic terms come from the source question.')),
  keyed(40, 7, 'definitions', 'The science of ethics discusses both _____ and _____.', ['Truthfulness, telling lies.', 'Honesty, balance.', 'Humanity, cruelty.', 'Life, death.'], 'A', 'A', 'A is the intended virtue-and-opposing-vice example. C is also defensible if “humanity” means humane conduct, so both A and C are accepted. B names two favorable qualities, not the contrast sought. The original stem does not uniquely distinguish A from C.', {acceptedOptionIds: ['A', 'C']}),
  keyed(42, 8, 'definitions', 'The benefits of interaction with people include:', ['Actualizing virtues.', 'Learning and teaching.', 'Self-building and developing spiritually.', 'All of the above.'], 'D', 'D', 'D combines the source’s three benefits. The notes cover cultivating traits, learning and social conduct; none of these benefits excludes the others. Duplicate compilation Q67 is not scored again.'),
  keyed(56, 10, 'honesty', 'A good friend will:', ['Not let you achieve something by wrong means.', 'Praise your success even if you achieved it by wrong means.', 'Not say anything.'], 'B', 'A', 'The printed key B endorses wrongdoing and contradicts the honesty lesson. A fits first-term p. 21, which warns against compromising integrity. The correction is explicit; loyalty does not require approving dishonest means.'),
  keyed(70, 13, 'intention', 'On which factor does the depth of our action depend?', ['Good intention.', 'Money.', 'Bragging.', 'None.'], 'A', 'A', 'The sincerity lesson makes intention central and rejects ostentation. Money or boasting do not by themselves establish moral value.', section('sep17-ostentation', 'Outwardly good actions can be spoiled by their motive, review p. 5.')),
  keyed(71, 13, 'intention', 'In Islam, _____ is more important than _____.', ['Quantity, quality.', 'Chastity, quantity.', 'Quality, quantity.', 'None.'], 'C', 'C', 'C expresses the intended course contrast: moral worth is not just the numerical size of an act. The review’s sincerity and sustained-good-action discussions support this emphasis, without implying that the amount of beneficial action never matters.', section('sep17-repentance', 'Small, sustained good actions versus an abandoned impressive act, review p. 13.')),
  keyed(72, 13, 'learning', 'Which of the following is not considered a moral value for learning?', ['Sincerity and intention.', 'Asking reasonable questions.', 'Knowing necessary things.', 'Causing a dispute.'], 'B', 'D', 'The printed key B is inconsistent with learning by reasonable questions. D is the intended exception: contentious questioning, not sincere inquiry. Nahjul Balagha saying 320 makes the distinction explicit.', {evidence: [`Nahjul Balagha, saying 320: ${sayings}`]}),
  keyed(73, 14, 'intention', 'It is said that an action without an intention is like:', ['A year without rain.', 'A body without spirit.', 'A magazine without a cover.', 'A religion without ethics.'], 'D', 'B', 'The question page highlights B, while the end-of-file answer sheet says D. B is the repeated analogy in the other source papers and agrees with the sincerity teaching. The conflicting answer sheet is not adopted.', section('sep17-ostentation', 'Intention gives the action its moral character; the exact body/spirit analogy is in the source papers.')),
  keyed(74, 14, 'learning', 'A student should refrain from:', ['Learning things that are not beneficial.', 'Gaining information that does not benefit them in the hereafter.', 'Choosing various fields to study.', 'All of the above.'], 'A', 'A', 'A is the broad useful-knowledge principle in the first-term learning lesson. C is not prohibited; choosing different fields is not itself wrong, so D cannot be correct. The lesson does not exclude beneficial worldly learning.'),
  keyed(75, 14, 'intention', 'Which factor, according to this paper, distinguishes Islam from other moral systems?', ['Valuing intention as well as action.', 'Judging an action by the money invested in it.', 'Belittling intention.', 'None of the above.'], 'B', 'A', 'A matches the review’s sincerity teaching; the printed/highlighted B is wrong. The paper’s comparative wording is overbroad: other ethical traditions also consider intention. Learn the importance of intention and action, not a claim of exclusive ownership of that idea.', section('sep17-ostentation', 'Intention versus money/status or outward appearance, review pp. 5–6.')),
  keyed(77, 14, 'learning', 'Allah sent His messengers to teach people and enhance moral values in order to _____ them.', ['Develop.', 'Purify.', 'Advance.', 'Modernize.'], 'B', 'B', 'The intended scriptural term is purification, as quoted in Lesson 3, p. 6 (Quran 62:2). This is the particular completion asked for, not a denial of other broader benefits.', {evidence: quran('62:2')}),
  keyed(79, 15, 'learning', 'Allah swears _____ times in Surah al-Shams to emphasize purification of the heart.', ['7.', '9.', '11.', '13.'], 'C', 'C', 'The course’s conventional count is eleven: sun, its brightness, moon, day, night, sky and its builder, earth and its spreader, soul and its fashioner (91:1–7). This depends on that traditional counting of the paired clauses; purification follows in 91:9.', {evidence: quran('91:1', '91:7', '91:9')}),
  keyed(81, 15, 'speech', 'Backbiting is allowed if:', ['The person being backbitten does not mind being talked about.', 'What is being said is not wrong or a lie.', 'It happens between the person’s friends in a mocking way.', 'None of the above.'], 'D', 'D', 'Truth or friendly company alone does not make harmful backbiting acceptable; D is the intended answer. A is imprecise because explicit consent and absence of disliked disclosure can affect the definition, so A is also accepted as a defensible reading. Necessary advice/complaints are not described by these options; this is not a blanket rule against reporting harm.', {acceptedOptionIds: ['A', 'D'], evidence: quran('49:12')}),
  keyed(82, 15, 'foundations', 'All of the following are included in the philosophy of sending prophets to mankind except:', ['Teach their people the Quran.', 'Purify their souls.', 'Show them the truth of life.', 'Killing non-religious people.'], 'D', 'D', 'D is the intended exception to teaching and moral purification in Lesson 1 and Lesson 3. The source’s first option generalizes the Quran to all prophets; that wording is historically imprecise. It does not change the intended nonviolent educational contrast.'),
  keyed(83, 16, 'speech', 'Mocking is:', ['Not allowed even between friends.', 'Could be by calling people names.', 'Immoral.', 'All of the above.'], 'D', 'D', 'Quran 49:11 prohibits degrading ridicule and offensive nicknames. D is intended where “mocking” means such harmful ridicule, not every consensual joke.', {evidence: quran('49:11')}),
  keyed(85, 16, 'learning', 'Which expresses the importance of learning according to verses of the Quran?', ['Comparison between a learner and a worshipper.', 'Sending prophets to mankind is to educate and teach them.', 'No limitation in learning.', 'Place of learning.'], 'B', 'B', 'Lesson 3, p. 6 cites Quran 62:2 concerning teaching and purification. The learner/worshipper comparison in A is presented as a tradition in this bank, not the Quranic verse asked for.', {evidence: quran('62:2')}),
  keyed(86, 16, 'learning', 'In Islam, the factors that can cause limitation in learning are:', ['The sex of the person.', 'The age of the person.', 'None of the above.', 'All of the above.'], 'C', 'C', 'Lesson 3, p. 7 says the pursuit of knowledge is not restricted by gender or stage of life. C is the intended answer about eligibility, not a denial of practical learning needs or age-appropriate education.'),
  keyed(87, 16, 'learning', 'Which is a tradition of Prophet Muhammad about the importance of learning?', ['No honor is like knowledge.', 'The superiority of a learned man to a worshipper is like the superiority of the moon to stars.', 'Learning never exhausts the mind.', 'The most complete gift of God is a life based on knowledge.'], 'B', 'B', 'B is identifiable in Sunan Abi Dawud 3641. This supports the source’s attribution and complements the course’s knowledge lesson; it is not a claim that the other statements lack ethical value.', {evidence: ['Primary hadith text: https://sunnah.com/abudawud:3641']}),
  keyed(89, 17, 'speech', 'Fill the blank in Quran 49:12: “Do not backbite about one another; is there any one of you _____ to eat from the flesh of his dead brother?”', ['In his life.', 'Hate and hate.', 'Who would like.', 'No one is correct.'], 'C', 'C', 'The rhetorical question asks whether anyone would like to do this. C is the supplied translation of the missing phrase, not permission for the act.', {evidence: quran('49:12')}),
  keyed(90, 17, 'speech', 'Fill the blank in Quran 49:11: “Do not let some men ridicule others ... _____ and do not insult one another by unpleasant nicknames.”', ['In the next of kin.', 'Zakat and the best deed.', 'And do not be sarcastic to each other.', 'And do not speak out.'], 'C', 'C', 'C is the source’s translation of the clause prohibiting mutual defamation (ولا تلمزوا أنفسكم). More idiomatically it means not insulting/defaming one another, rather than a blanket ban on speaking.', {evidence: quran('49:11')}),
  keyed(92, 18, 'learning', 'What three things are necessary for doing research as a physician?', ['Having good intentions.', 'Being familiar with past research on the subject.', 'Being trustworthy.', 'All of the above.'], 'D', 'D', 'This is a general research-integrity question, not a medical ruling. Sincerity, learning from previous work and honesty support D. Duplicate compilation Q95 is represented here; its printed C omits the other moral requirements.', {evidence: ['Review pp. 4–5 (reflection on past experience and intention); first-term pp. 19–21 (honesty).']}),
  keyed(93, 18, 'anger', 'What is necessary to keep in mind when criticizing someone or something?', ['It is best never to criticize what you say or think.', 'Be patient and tolerant of others even when they are wrong.', 'You should be harsh with others when they are wrong.', 'None of the above.'], 'D', 'B', 'B matches the humility lesson p. 14 on addressing mistakes politely and the anger/self-control lesson. The printed D rejects the only constructive option and is corrected.'),
  keyed(94, 18, 'forgiveness', '“The good and evil are not _____, so repel wrongdoing with good _____ instead. Then your enemies will turn into intimate _____.” (Quran 41:34)', ['Opposite / food / friends.', 'Friends / intentions / lovers.', 'The same / treatment / relations.', 'Equal / treatment / friends.'], 'D', 'D', 'D supplies the intended contrasting equality, better treatment and friendship. This is the source’s paraphrase of Quran 41:34, not a guarantee that every offender will become safe or friendly.', {evidence: quran('41:34')}),
  keyed(96, 19, 'honesty', 'What does the Quran say about trust?', ['Deliver back the trust to the owner.', 'To be a believer.', 'Never backbite anyone.', 'None of the above.'], 'A', 'A', 'Here “trust” means entrusted property/responsibility (amanah), not tawakkul. Quran 4:58 requires returning trusts to their rightful recipients; the honesty lesson also emphasizes trustworthiness.', {evidence: quran('4:58')}),
]);

export const compilation2017 = paper('2017-additional-selection', 'Divine Ethics · 2017 compilation · additional questions', 73,
  'Ten additional relevant items from the self-described student-derived September 2017 compilation. Questions already represented in the 99-item selection are not copied again. This is a selected compilation, not a newly authenticated exam sitting. Original course level is unconfirmed; relevance is based on the review and first-term notes.', [
  question(6, 2, 'faith', 'Which verse, in the source’s Ibrahim example, demonstrates submission to God?', ['The angels prostrated except Iblees, who was arrogant and among the unbelievers.', 'Those who had faith and righteous deeds will have gardens beneath which rivers flow.', 'When his Lord said “Submit”, he said “I have submitted to the Lord of the worlds.”'], 'C', 'The question specifically asks for Ibrahim’s response in Quran 2:131. The original gives Arabic and English versions of each option; the English meanings are retained here.', {evidence: quran('2:131')}),
  question(7, 2, 'faith', 'Faith is accompanied with:', ['Prayer.', 'Practice.', 'Saying.'], 'B', 'B is the comprehensive intended completion: faith is expressed in conduct, not just a verbal claim. Prayer can be part of practice, but does not encompass all of it.', {...section('dhikr', 'Practical remembrance expresses inward faith in conduct, review p. 17.'), evidence: [`Nahjul Balagha, saying 227: ${sayings}`]}),
  question(8, 2, 'learning', 'Which of the following is an obstacle in the way of learning?', ['Being very hasty in judgment.', 'Following carnal desires.', 'Both A and B.'], 'C', 'The notes’ piety/knowledge lesson describes obstructing desires; the review’s reflection/planning teaching cautions against haste. Both obstruct careful understanding.'),
  question(17, 4, 'faith', 'Which of the following is NOT a way of improving faith?', ['Submission to the commands of Allah.', 'Remembering God and Judgment Day.', 'Backbiting.'], 'C', 'C conflicts with the ethical use of speech; A and B express obedient conduct and remembrance. Review pp. 9–10 distinguishes awareness and practical conduct.', {...section('sep17-gratitude-levels', 'Speech used for good rather than backbiting, review p. 10.'), evidence: quran('49:12')}),
  question(34, 7, 'intention', 'Which statement is correct?', ['Only the action itself must be good.', 'Both the action and the intention of the doer must be good.', 'Only the intention of the doer must be good.'], 'B', 'Neither a good-looking act with an ostentatious motive nor a good intention alone suffices in this teaching. The review p. 5 explains the importance of both motive and conduct.', section('sep17-ostentation', 'A good-looking act can be spoiled by its intention; neither side alone is enough.')),
  question(36, 8, 'trust', '“And when I get ill, He is the one who heals me.” This Quranic statement is made by which prophet?', ['Prophet Muhammad.', 'Prophet Ibrahim.', 'Prophet Jesus.'], 'B', 'Quran 26:69–80 presents Ibrahim speaking. This is about attribution of the verse; the related trust lesson does not tell a patient to abandon medical means.', {evidence: quran('26:69', '26:80')}),
  question(40, 8, 'definitions', 'What is the meaning of applied ethics?', ['The ethics that should be applied in our life.', 'Normative ethics applicable in different fields.', 'It is exactly theoretical ethics.'], 'B', 'Lesson 2, p. 5 defines application of moral principles in a particular field. B is more precise than A; applied ethics is not simply identical to theoretical inquiry.'),
  question(42, 9, 'learning', 'When the Prophet says “Seek knowledge even in China”:', ['He means that you have to travel to that country for learning.', 'China is an example: even if learning requires travel a very long distance, you should pursue it.', 'Because many Chinese are not believers, the lecturer need not be a believer.'], 'B', 'Lesson 3, p. 7 uses this saying to reject geographic restriction. This tests the course’s intended interpretation; it does not assert independent authentication of the saying’s transmission.'),
  question(47, 10, 'humility', 'The supplied saying names jealousy, self-admiration and pride as destroyers of religion. Which listed immoral act should a physician avoid on that basis?', ['Backbiting.', 'Jealousy.', 'Mocking and ridiculing.'], 'B', 'Jealousy is expressly named in the quoted premise. The question does not imply that backbiting or ridicule is acceptable. Compare envy among the review’s obstacles to gratitude.', section('sep17-gratitude-obstacles', 'Envy of others’ blessings, review p. 11.')),
  question(57, 11, 'learning', 'All of the following are moral conditions of doing research except:', ['Being familiar with the past history of that research.', 'Considering copying and pasting.', 'Being brave enough to express opinions frankly.'], 'B', 'B is intended as unacknowledged copying/plagiarism. Honest quotation with attribution is different and is not forbidden by this question. The notes’ honesty and integrity discussion supports the distinction.'),
], {numberingNote: 'The original compilation is unnumbered. “Source item” numbers are stable editorial ordinals in reading order, not claimed printed question numbers.', originalOrderClaim: false, dateEvidence: 'Compilation cover says September Program 2017; no specific sitting date is asserted.'});

export const photo20 = paper('photo-20-additional-selection', 'Divine Ethics · 20-question photos · additional selection', 20,
  'Six additional relevant questions from the separate 20-question photo paper. Repeated intention, learning and backbiting questions are represented in the other collections instead. Physician-duty items, uncertain faith-degree items and ambiguous statements are excluded. No identifying cover or official I/II designation is available.', [
  question(9, 2, 'faith', 'Which of the following is not one of the stages of faith?', ['Having an Islamic name.', 'Confessing by tongue.', 'Having enough knowledge about it.', 'Practicing what we believe in.'], 'A', 'A name alone does not establish inward belief or conduct. The knowledge/acknowledgment/action formulation appears in Nahjul Balagha saying 227; compare practical remembrance in the review.', {evidence: [`Nahjul Balagha, saying 227: ${sayings}`]}),
  question(10, 2, 'faith', 'Which of the following is true?', ['Any Muslim is faithful, but not vice versa.', 'Any faithful person is a Muslim, but not vice versa.', 'There is no relationship between faith and Islam.', 'Faith comes first and then Islam.'], 'B', 'Within this course’s technical distinction, inward iman is more than outward profession of Islam; Quran 49:14 illustrates the distinction. This is not permission to pronounce judgment on an individual’s sincerity or to deny moral worth to other people.', {evidence: quran('49:14')}),
  question(17, 4, 'humility', 'A person finds a good habit or attribute in a friend and says “I wish I also had it.”', ['This is jealousy and is bad.', 'It is not jealousy and is not bad.', 'This is jealousy but exceptionally is not bad.', 'None of them.'], 'B', 'The intended distinction is constructive emulation without wishing the other person to lose the good quality, versus destructive envy. The stem states no wish to deprive the friend. Compare the review’s envy obstacle; this is not the same as coveting another’s loss.'),
  question(18, 4, 'speech', '“Backbiting” is:', ['Talking about a wrong habit which exists in a person.', 'Talking about a wrong habit which does not exist in a person.', 'The same as accusation.', 'Exactly the same as insulting a person.'], 'A', 'A is closest among these choices, but is an incomplete definition: the relevant truthful disclosure is something the absent person would dislike. False attribution is slander. Necessary advice or reporting harm must not be conflated with malicious gossip.', {evidence: ['Primary definition of backbiting and slander: https://sunnah.com/muslim:2589']}),
  question(19, 4, 'speech', 'What does the Quran say about mocking others?', ['If it is normal and a little, it is allowed.', 'Do not mock others because they may be better than you.', 'Mocking people of other nationalities has no problem.', 'None of them.'], 'B', 'Quran 49:11 explicitly gives the possibility that the ridiculed people are better than those ridiculing them. Nationality is not a license for humiliation.', {evidence: quran('49:11')}),
  question(20, 4, 'learning', 'The source quotes: “When a believer dies and leaves behind a paper on which there is knowledge ...”. What does this saying indicate?', ['The importance of teaching and writing.', 'The importance of doing research.', 'When someone dies, they should leave a will.', 'Before we die, we should clear our debts.'], 'A', 'The photographed mark is B (research), while A is the most direct reading of a written legacy that transmits knowledge. The notes p. 6 connect teaching with writing by the pen; the fragment does not specify how that knowledge was obtained. Both A and the supplied broader research interpretation B are accepted for this imprecise item. The incomplete saying is not presented as an independently authenticated complete hadith.', {acceptedOptionIds: ['A', 'B']}),
]);

// Preserve the visible annotations independently from our editorial study keys.
for (const row of photo20.questions) row.providedKey = ({9:'A',10:'B',17:'B',18:'A',19:'B',20:'B'})[row.number];

// These original items remain downloadable but are not safe single-best-answer
// scoring material. Do not manufacture certainty by accepting an unsupported key.
photo30.questions = photo30.questions.filter(q => q.number !== 22);
photo30.kind = 'selected-source-questions';
photo30.excludedSourceNumbers = [22];
photo30.note = photo30.note.replace('Complete Q1–30 body', 'Complete Q1–30 source body; 29 scored questions (Q22 withheld: its all-of-the-above key depends on an unverified translated claim)');
compilation99.questions = compilation99.questions.filter(q => ![81, 82].includes(q.number));
compilation99.excludedSourceNumbers = Array.from({length:99},(_,i)=>i+1).filter(n=>!compilation99.questions.some(q=>q.number===n));

export const expandedPapers = [photo30, report2021, compilation99, compilation2017, photo20];
